@app.route("/logout")
def logout():
    chat_id = session.get("chat_id")
    if chat_id and os.environ.get("DATABASE_URL"):
        try:
            with psycopg.connect(os.environ["DATABASE_URL"]) as conn:
                with conn.cursor() as cur:
                    cur.execute("DELETE FROM sempa_chatverlauf WHERE chat_id = %s", (chat_id,))
        except Exception:
            app.logger.exception("Chatverlauf konnte beim Abmelden nicht gelöscht werden")
            return "Abmelden nicht möglich: Chatverlauf konnte nicht gelöscht werden. Bitte erneut versuchen.", 503
    session.clear()
    return redirect("/login")

@app.route("/", methods=["GET", "POST"])
def startseite():
    if not session.get("angemeldet"):
        return redirect("/login")

    aufgaben = lade_aufgaben()
    antwort = ""
    frage_gesendet = False
    bearbeiten_aufgabe = None
    smart_preview = []
    smart_token = ""
    mission_edit_preview = None
    mission_edit_token = ""

    if request.method == "POST":
        neue_aufgabe = request.form.get("neue_aufgabe", "").strip()
        speichern_nummer = request.form.get("speichern_nummer")
        bearbeiten = request.form.get("bearbeiten")
        erledigt = request.form.get("erledigt")

        if request.form.get("mission_edit_befehl", "").strip():
            mission_edit_preview, fehler = mission_edit_vorschlag(request.form['mission_edit_befehl'][:300], aufgaben)
            if mission_edit_preview:
                mission_edit_token = URLSafeTimedSerializer(app.secret_key, salt='sempa-edit-v30').dumps(
                    {'edit': mission_edit_preview, 'chat': _chat_id()})
                antwort = 'Bitte die Änderung prüfen und ausdrücklich bestätigen.'
            else:
                antwort = fehler
        elif request.form.get('mission_edit_confirm'):
            try:
                data = URLSafeTimedSerializer(app.secret_key, salt='sempa-edit-v30').loads(
                    request.form['mission_edit_confirm'], max_age=900)
                v = data['edit']
                if data.get('chat') != _chat_id() or not isinstance(v, dict) or set(v) != {'aktion','id','text','neu_text','alt_uhrzeit','neu_uhrzeit','faelligkeit','neu_faelligkeit','prioritaet','beschreibung'} or v['aktion'] not in ('aendern','loeschen') or not re.fullmatch(r'ohne|morgens|vormittags|mittags|nachmittags|abends|nachts|(?:[01]\d|2[0-3]):[0-5]\d', str(v['neu_uhrzeit'])) or not re.fullmatch(r'heute|morgen|ohne|\d{4}-\d{2}-\d{2}', str(v['neu_faelligkeit'])):
                    raise BadSignature('Ungueltige Aenderung')
                if mission_edit_speichern(v):
                    antwort = ('✓ Mission sicher gelöscht.' if v['aktion'] == 'loeschen' else '✓ Mission aktualisiert: ' + v['neu_faelligkeit'] + ' · ' + v['neu_uhrzeit'])
                else:
                    antwort = 'ℹ️ Mission wurde bereits geändert oder gelöscht. Bitte erneut prüfen.'
                aufgaben = lade_aufgaben()
            except (BadSignature, SignatureExpired, KeyError, TypeError, ValueError):
                antwort = 'Änderungsvorschau abgelaufen oder ungültig. Bitte erneut prüfen.'
        elif request.form.get("smart_missions", "").strip():
            smart_preview = mission_parts(request.form["smart_missions"][:1200])
            if smart_preview:
                smart_token = mission_token().dumps({"items": smart_preview, "chat": _chat_id()})
                antwort = "Bitte die erkannten Missionen kontrollieren und bestätigen."
            else:
                antwort = "Keine Mission erkannt. Bitte den Satz anders formulieren."
        elif request.form.get("smart_confirm"):
            try:
                data = mission_token().loads(request.form["smart_confirm"], max_age=900)
                if data.get("chat") != _chat_id():
                    raise BadSignature("Sitzung passt nicht")
                items = data["items"]
                if not isinstance(items, list) or not (1 <= len(items) <= 10):
                    raise BadSignature("Ungültige Aufgaben")
                for a in items:
                    if not isinstance(a, dict) or set(a) != {"text", "prioritaet", "faelligkeit", "uhrzeit"} or not isinstance(a["text"], str) or len(a["text"]) > 300 or a["prioritaet"] not in ("hoch", "normal", "niedrig") or a["faelligkeit"] not in ("heute", "morgen", "ohne") or not isinstance(a["uhrzeit"], str) or not re.fullmatch(r"ohne|morgens|vormittags|mittags|nachmittags|abends|nachts|(?:[01]\d|2[0-3]):[0-5]\d", a["uhrzeit"]):
                        raise BadSignature("Ungültige Aufgabe")
                neu_gespeichert = save_missions(items, request.form["smart_confirm"])
                aufgaben = lade_aufgaben()
                antwort = (f"✓ {len(items)} Missionen gespeichert." if neu_gespeichert
                           else "ℹ️ Dieser Plan wurde bereits gespeichert. Keine doppelten Missionen angelegt.")
            except (BadSignature, SignatureExpired, KeyError, TypeError, ValueError):
                antwort = "Vorschau abgelaufen oder ungültig. Bitte den Plan erneut prüfen."
        elif neue_aufgabe:
            prioritaet = "normal"
            faelligkeit = "ohne"
            uhrzeit = "ohne"
            uhrzeit = mission_uhrzeit(neue_aufgabe)
            klein = neue_aufgabe.lower()
            if "heute" in klein:
                faelligkeit = "heute"
            elif "morgen" in klein:
                faelligkeit = "morgen"
            if "nicht dringend" in klein or "später" in klein:
                prioritaet = "niedrig"
            elif "wichtig" in klein or "dringend" in klein:
                prioritaet = "hoch"
            if os.environ.get("DATABASE_URL"):
                with psycopg.connect(os.environ["DATABASE_URL"]) as conn:
                    with conn.cursor() as cur:
                        cur.execute("INSERT INTO aufgaben (text, prioritaet, faelligkeit, uhrzeit) VALUES (%s, %s, %s, %s)", (neue_aufgabe, prioritaet, faelligkeit, uhrzeit))
            else:
                aufgaben.append({"text": neue_aufgabe, "prioritaet": prioritaet, "faelligkeit": faelligkeit, "uhrzeit": uhrzeit})
                with open("aufgaben.json", "w") as datei:
                    json.dump(aufgaben, datei, ensure_ascii=False, indent=2)
            aufgaben = lade_aufgaben()
            antwort = "✓ Mission hinzugefügt."

        elif speichern_nummer is not None and speichern_nummer.isdigit():
            nummer = int(speichern_nummer)
            neuer_text = request.form.get("bearbeiten_text", "").strip()
            if 0 <= nummer < len(aufgaben) and neuer_text:
                aufgaben[nummer]["text"] = neuer_text
                if os.environ.get("DATABASE_URL"):
                    with psycopg.connect(os.environ["DATABASE_URL"]) as conn:
                        with conn.cursor() as cur:
                            cur.execute("UPDATE aufgaben SET text = %s WHERE id = %s", (neuer_text, aufgaben[nummer]["id"]))
                else:
                    with open("aufgaben.json", "w") as datei:
                        json.dump(aufgaben, datei, ensure_ascii=False, indent=2)
                aufgaben = lade_aufgaben()
                antwort = "✓ Mission aktualisiert."

        elif bearbeiten is not None and bearbeiten.isdigit():
            nummer = int(bearbeiten)
            if 0 <= nummer < len(aufgaben):
                bearbeiten_aufgabe = dict(aufgaben[nummer], nummer=nummer)

        elif erledigt is not None and erledigt.isdigit():
            nummer = int(erledigt)
            if 0 <= nummer < len(aufgaben):
                if os.environ.get("DATABASE_URL"):
                    with psycopg.connect(os.environ["DATABASE_URL"]) as conn:
                        with conn.cursor() as cur:
                            cur.execute("DELETE FROM aufgaben WHERE id = %s", (aufgaben[nummer]["id"],))
                else:
                    aufgaben.pop(nummer)
                    with open("aufgaben.json", "w") as datei:
                        json.dump(aufgaben, datei, ensure_ascii=False, indent=2)
                aufgaben = lade_aufgaben()
                antwort = "✓ Mission abgeschlossen."

        elif request.form.get("tagesplan"):
            if not aufgaben:
                antwort = "Du hast aktuell keine Aufgaben."
            else:
                aufgaben_text = "\n".join(f"- {a['text']} (Priorität: {a['prioritaet']}, Fälligkeit: {a['faelligkeit']}, Uhrzeit: {a.get('uhrzeit', 'ohne')})" for a in aufgaben)
                try:
                    antwort = paid_text("Erstelle einen kurzen, realistischen Tagesplan aus meinen Aufgaben. Priorisiere wichtige und heute fällige Aufgaben.", aufgaben_text)
                except Exception:
                    app.logger.exception("Tagesplan konnte nicht erstellt werden")
                    antwort = "Der Tagesplan ist momentan nicht verfügbar. Bitte später erneut versuchen."

        else:
            frage = request.form.get("frage", "").strip()
            if frage:
                # SEMPA 3.0.1: Missionsbefehle aus dem normalen Matrix-Chat
                # zuerst an den sicheren Editor leiten (niemals direkt löschen).
                ist_missionsbefehl = bool(re.search(
                    r"\b(?:verschieb(?:e|en)|änder(?:e|n)|aender(?:e|n)|"
                    r"setz(?:e|en)|lösch(?:e|en)|loesch(?:e|en)|entfern(?:e|en))\b",
                    frage, re.I))
                if ist_missionsbefehl:
                    mission_edit_preview, fehler = mission_edit_vorschlag(frage[:300], aufgaben)
                    if mission_edit_preview:
                        mission_edit_token = URLSafeTimedSerializer(
                            app.secret_key, salt='sempa-edit-v30').dumps(
                                {'edit': mission_edit_preview, 'chat': _chat_id()})
                        antwort = 'Bitte die Mission in der Vorschau prüfen und ausdrücklich bestätigen.'
                    else:
                        antwort = fehler
                else:
                    frage_gesendet = True
                    try:
                        antwort = answer_with_memory(frage)
                    except Exception:
                        app.logger.exception("KI-Anfrage fehlgeschlagen")
                        antwort = "Die KI ist momentan nicht erreichbar. Bitte später erneut versuchen."

    heute = mission_sortieren(aufgaben, "heute")
    morgen = mission_sortieren(aufgaben, "morgen")
    spaeter = mission_sortieren(aufgaben, "spaeter")
    try:
        chat_nachrichten = _chat_history()
    except Exception:
        app.logger.exception("Chatverlauf konnte nicht geladen werden")
        chat_nachrichten = []
    return render_template_string(HTML, antwort=antwort, frage_gesendet=frage_gesendet, chat_nachrichten=chat_nachrichten, heute=heute, morgen=morgen, spaeter=spaeter, bearbeiten_aufgabe=bearbeiten_aufgabe, budget=budget_display(), smart_preview=smart_preview, smart_token=smart_token, mission_edit_preview=mission_edit_preview, mission_edit_token=mission_edit_token)


@app.route("/api/transkribieren", methods=["POST"])
def api_transkribieren():
    # Nur eingeloggte Nutzer dürfen kostenpflichtige Transkriptionen auslösen.
    if not session.get("angemeldet"):
        return jsonify(fehler="Bitte erneut anmelden."), 401
    audio = request.files.get("audio")
    if audio is None:
        return jsonify(fehler="Keine Audioaufnahme erhalten."), 400
    # 10 MB sind für die auf 30 Sekunden begrenzte Aufnahme ausreichend.
    audio.stream.seek(0, 2)
    size = audio.stream.tell()
    audio.stream.seek(0)
    if size < 1 or size > 10 * 1024 * 1024:
        return jsonify(fehler="Die Aufnahme ist leer oder zu groß (max. 10 MB)."), 400
    name = (audio.filename or "").lower()
    extension = name.rsplit(".", 1)[-1] if "." in name else ""
    if extension not in {"mp4", "m4a", "webm", "wav", "ogg", "mp3"}:
        return jsonify(fehler="Dieses Audioformat wird nicht unterstützt."), 400
    if not change_budget(VOICE_RESERVE_EUR, require_space=True):
        return jsonify(fehler="Monatsbudget erreicht. Spracherkennung ist vorerst gesperrt."), 429
    try:
        recording = io.BytesIO(audio.read())
        recording.name = "aufnahme." + extension
        result = client.audio.transcriptions.create(
            model="gpt-4o-mini-transcribe", file=recording, language="de"
        )
        # Konservativer Festbetrag pro Aufnahme (maximal 30 Sekunden).
        change_budget(Decimal("0.01") - VOICE_RESERVE_EUR)
        return jsonify(text=result.text)
    except Exception:
        change_budget(-VOICE_RESERVE_EUR)
        app.logger.exception("Spracherkennung fehlgeschlagen")
        return jsonify(fehler="Spracherkennung momentan nicht verfügbar. Bitte erneut versuchen."), 502

@app.route("/api/frage", methods=["POST"])
def api_frage():
    if not session.get("angemeldet"):
        return {"fehler": "Bitte anmelden."}, 401
    daten = request.get_json(silent=True) or {}
    frage = daten.get("frage", "").strip()

    if not frage:
        return {"antwort": "Bitte stelle mir eine Frage."}, 400

    if not session.get("angemeldet"):
        return {"fehler": "Bitte anmelden."}, 401
    return {"antwort": answer_with_memory(frage)}

@app.route("/api/aufgaben", methods=["GET"])
def api_aufgaben():
    aufgaben = lade_aufgaben()
    return {"aufgaben": aufgaben}
@app.route("/api/aufgaben", methods=["POST"])
def api_aufgabe_hinzufuegen():
    daten = request.get_json(silent=True) or {}
    text = daten.get("text", "").strip()

    if not text:
        return {"fehler": "Aufgabe darf nicht leer sein."}, 400

    aufgaben = lade_aufgaben()

    faelligkeit = "ohne"
    if "heute" in text.lower():
        faelligkeit = "heute"
    elif "morgen" in text.lower():
        faelligkeit = "morgen"
    prioritaet = "normal"
    if "nicht dringend" in text.lower() or "später" in text.lower():
        prioritaet = "niedrig"
    elif "wichtig" in text.lower() or "dringend" in text.lower():
        prioritaet = "hoch"

    neue_aufgabe = {
        "text": text,
        "prioritaet": prioritaet,
        "faelligkeit": faelligkeit,
        "uhrzeit": mission_uhrzeit(text)
    }

    aufgaben.append(neue_aufgabe)
    if os.environ.get("DATABASE_URL"):
        with psycopg.connect(os.environ["DATABASE_URL"]) as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """INSERT INTO aufgaben (text, prioritaet, faelligkeit, uhrzeit)
                       VALUES (%s, %s, %s, %s)""",
                    (text, prioritaet, faelligkeit, "ohne")
                )
    else:
        with open("aufgaben.json", "w") as datei:
            json.dump(aufgaben, datei, ensure_ascii=False, indent=2)
    return {"erfolg": True}
@app.route("/api/tagesplan", methods=["GET"])
def api_tagesplan():
    if not session.get("angemeldet"):
        return {"fehler": "Bitte anmelden."}, 401
    aufgaben = lade_aufgaben()

    if not aufgaben:
        return {"tagesplan": "Du hast aktuell keine Aufgaben."}

    aufgaben_text = "\n".join(
        f"- {a['text']} (Priorität: {a['prioritaet']}, Fälligkeit: {a['faelligkeit']}, Uhrzeit: {a.get('uhrzeit', 'ohne')})"
        for a in aufgaben
    )

    if not session.get("angemeldet"):
        return {"fehler": "Bitte anmelden."}, 401
    return {"tagesplan": paid_text("Erstelle einen kurzen, realistischen Tagesplan aus meinen Aufgaben. Priorisiere wichtige und heute fällige Aufgaben.", aufgaben_text)}


